import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gemm_sigmoid_scaling_res_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gemm_sigmoid_scaling_residual_kernel(
    const float* __restrict__ A,
    const float* __restrict__ W,
    const float* __restrict__ bias,
    float* __restrict__ out,
    float scaling_factor,
    int batch_size,
    int input_size,
    int hidden_size
) {
    int row = blockIdx.x;
    int col = threadIdx.x;
    if (row < batch_size && col < hidden_size) {
        float val = 0.0f;
        for (int i = 0; i < input_size; i++) {
            val += A[row * input_size + i] * W[col * input_size + i];
        }
        val += bias[col];
        float original_val = val;
        float x = 1.0f / (1.0f + expf(-val));
        x *= scaling_factor;
        val = original_val + x;
        out[row * hidden_size + col] = val;
    }
}

torch::Tensor gemm_sigmoid_scaling_residual_forward(
    torch::Tensor A,
    torch::Tensor W,
    torch::Tensor bias,
    float scaling_factor
) {
    const auto batch_size = A.size(0);
    const auto input_size = A.size(1);
    const auto hidden_size = W.size(0);

    auto out = torch::zeros({batch_size, hidden_size}, A.options());

    dim3 grid(batch_size);
    dim3 block(hidden_size);

    gemm_sigmoid_scaling_residual_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        W.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        scaling_factor,
        batch_size,
        input_size,
        hidden_size
    );

    return out;
}
"""

