class ModelNew(nn.Module):
    """
    Optimized model implementing GEMM + Sigmoid + Scaling + ResidualAdd in a fused custom CUDA kernel.
    """
    def __init__(self, input_size, hidden_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.empty(hidden_size, input_size))
        self.bias = nn.Parameter(torch.empty(hidden_size))
        nn.init.xavier_uniform_(self.weight)
        nn.init.zeros_(self.bias)
        self.scaling_factor = scaling_factor

    def forward(self, x):
        return gemm_sigmoid_scaling_res_op.gemm_sigmoid_scaling_residual_forward(
            x, self.weight, self.bias, self.scaling_factor
        )

